  str_n34_dispatch_task_4_log_10 = "10 ชั่วโมงหลังจากการสืบสวน\nลมเริ่มเย็นลงแล้ว... ถึงเวลาออกเดินทางแล้วนะ",
  str_n34_dispatch_task_5_log_1 = "1 ชั่วโมงหลังจากเริ่มการสืบสวน\nทะเลทรายสิ้นสุดลงที่นี่ และใครจะคิดว่าจะมีหนองน้ำชื้นๆ อยู่ในที่แบบนี้?",
  str_n34_dispatch_task_5_log_2 = "1.5 ชั่วโมงหลังจากเริ่มการสืบสวน\nคุณจะไม่เชื่อว่าพืชในหนองน้ำนี้แปลกแคล้วแค่ไหน! หลายต้นมีหนามและขน และนี่คือข้อสังเกต - พวกมันแสดงอาการเคลื่อนไหว! บางต้นยังหายใจออกลมเย็นอีกด้วย!",
  str_n34_dispatch_task_5_log_3 = "2 ชั่วโมงหลังจากเริ่มสืบสวน\nไม่มีใครอนุญาตให้แตะต้องพืชที่นี่ เพราะอาจมีพิษ",
  str_n34_dispatch_task_5_log_4 = "2.2 ชั่วโมงหลังจากเริ่มสืบสวน\nฉันจะเอาอัลเทอร์-ดาบมาเปิดทางออก โดยส่วนใหญ่เพื่อแตกน้ำแข็ง",
  str_n34_dispatch_task_5_log_5 = "2.5 ชั่วโมงในการสืบสวน\nบึงที่เรากำลังเดินนี้เป็นพื้นที่อันตรายจริง ๆ เนื่องจากน้ำแข็งบางๆ ที่หักง่าย ถ้าไม่ระวังในการเดิน คุณอาจพังลงไปและติดอยู่ในน้ำแข็ง แม้เราจะสามารถดึงคุณขึ้นมาได้ คุณก็ยังจะเปียกชุ่ม ในอากาศหนาวเย็นขนาดนี้ นั่นคือทางลัดสู่อาการตัวเย็นอย่างรวดเร็ว",
  str_n34_dispatch_task_5_log_6 = "3 ชั่วโมงหลังจากเริ่มสืบสวน\nพบแพลตฟอร์มดินที่แข็งแรง เราจะพัก 3 ชั่วโมงเพื่อตั้งกองไฟและอบอุปกรณ์กับรองเท้าของเรา",
  str_n34_dispatch_task_5_log_7 = "6 ชั่วโมงหลังจากการสืบสวน\nเชื่อไม่ได้เลยค่ะ—ไม่มีอิคลิพไซท์มากวนเรา! นี่เริ่มน่าเบื่อมากแล้ว!",
  str_n34_dispatch_task_5_log_8 = "6.2 ชั่วโมงหลังจากเริ่มการสืบสวน\nฉันสงสัยว่าอิคลิพไซท์คงไม่เคยคิดว่าออโรเรียนจะผ่านหนองน้ำนี้ ความท้าทายของเราคือความเสี่ยงที่มาจากธรรมชาติที่อยู่ใกล้เคียงเท่านั้น พักค่ายเสร็จแล้วทุกคน—เรามาก้าวหน้าต่อกันเถอะ",
